\begin{theorem}[polynomial-like restriction; Kahn I, psiql2.tex, ll.~60--77]\label{thm:kahn-psql-restriction}
Let \(F=(i,f)\colon\BU'\to\BU\) be a \(\psi\)-polynomial-like map of
degree \(d\ge2\) with filled Julia set \(K\) and \(K'=i^{-1}(K)\).
Then there is an open set \(U\subset\BU\) with \(K\subset U\) such
that, writing \(U'=f^{-1}(U)\subset\BU'\):
\begin{enumerate}
\item \(f\colon U'\to U\) is a proper degree-\(d\) branched covering;
\item \(i|_{U'}\) is an embedding;
\item \(i(U')\subset U\); and
\item \(\Mod\bigl(U\sm i(U')\bigr)\ge\mu>0\), where \(\mu\) can be
taken uniform over all such maps with \(d\) bounded and
\(\Mod(\BU\sm K)\) bounded below.
\end{enumerate}
In particular \(f\circ(i|_{U'})^{-1}\colon i(U')\to U\) is a
polynomial-like map of degree \(d\): every \(\psi\)-polynomial-like map
carries an \emph{embedded} polynomial-like germ, with modulus
controlled by the modulus of the ambient pair.
\end{theorem}

\begin{proposition}[dynamical localization; Kahn I, psiql2.tex, ll.~510--546]\label{prop:kahn-dynamical-localization}
Let \((i,f)\colon(\BU',K')\to(\BU,K)\) be a \(\psi\)-polynomial-like
map of degree \(d\), and suppose:
\begin{enumerate}
\item \(A\subset K\) is an FJ-set, and \(A'=i^{-1}(A)\);
\item \(B\subset K\) is compact and \(\BU\sm B\) is connected;
\item \(A\) is a component of \(B\);
\item \(A'\) is a component of \(f^{-1}(A)\);
\item \(i^{-1}(B)\subset f^{-1}(B)\) (see the caveat on the source's
literal wording); and
\item all branch values of \(f\) lie in \(B\).
\end{enumerate}
Set \(T=(\BU\sm B)\cup A\) and \(T'=(\BU'\sm f^{-1}B)\cup A'\).  Then
\((T,A)\) and \((T',A')\) are marked Riemann surfaces and the
restrictions of \(i\) and \(f\) are morphisms.  Writing \(\BV=T_A\)
and \(\BV'=T'_{A'}\) for the localizations:
\begin{enumerate}
\item[(a)] \(\BV\) and \(\BV'\) are disks;
\item[(b)] the localized pair
\((\widehat i,\widehat f)\colon(\BV',\widehat{A'})\to(\BV,\widehat A)\)
is a \(\psi\)-polynomial-like map whose degree is the local degree
\(d_{A'}\) of \(f\) at \(A'\), with \(\widehat i\) an immersion and
\(\widehat f\) a branched covering;
\item[(c)] since
\(\pi_{T,A}\colon\BV\sm\widehat A\to\BU\sm B\) is a covering map, the
Poincar\'e length of the core curve of \(\BV\sm\widehat A\) equals the
Poincar\'e length of the closed geodesic of \(\BU\sm B\) that goes
around \(A\).
\end{enumerate}
The pair \((\widehat i,\widehat f)\) is the \emph{dynamical
localization of \(f\) at \(A\) with the removal of \(B\)}.
\end{proposition}
